import logo from './logo.svg';

import { BrowserRouter, Routes, Route } from 'react-router-dom';

import Home from './pages/HomeComponent';
import Login from './pages/loginComponent';
import Register from './pages/registerComponent';
import Post from './pages/postComponent';
import Search from './pages/searchComponent';
import Nav from './pages/navComponent';
import Result from './pages/resultComponent';
import UploadPost from './pages/updatePostComponent';
import Form from './pages/CustomerRequestFormComponent';
import Fotter from './pages/footerComponent';
import ChatPage from './pages/chatPageComponent';
import Welcome from './pages/WelcomeComponent';

function App() {
  return (
    <BrowserRouter>

      <Fotter/>

      <Routes>

        <Route path="/" element={<Home />} />

        <Route path="/welcome" element={<Welcome />} />
        <Route path="/login" element={<Login />} />
        <Route path="/register" element={<Register />} />

        <Route path="/form" element={<Form />} />

        <Route path="/post/:id" element={<Post />} />

        <Route path="/search" element={<Search />} />
        <Route path="/results" element={<Result />} />

        <Route path="/chat" element={<ChatPage />} />

        <Route path="/add/post" element={<UploadPost />} />


      </Routes>
      <Nav/>

    </BrowserRouter>
  );
}

export default App;
